-- invoice items: inward_no taken straight from the Sale PDF.
-- 88 lines whose PDF inward_no is not a real batch (Old/Kaushik/Increase/SKY) -> NULL,
-- so Stock.tsx values them from remaining opening stock.

-- mark fully-paid bills so status is right without opening the app
update public.invoices i set invoice_type = i.invoice_type
where i.id in (select distinct invoice_id from public.invoice_items);

commit;
